/**
 * Package builder, turns a family into a developer-ready ZIP.
 *
 * Everything is produced in the browser: SVG files, PNG rasters, React and Vue
 * components, a sprite, JSON metadata, TypeScript types, a README and a LICENSE.
 * `fflate` (already a dependency) writes the archive.
 *
 * SAFETY: every path inside the archive is built from a slug that has been
 * stripped to `[a-z0-9-]`, so nothing a user types can escape the package
 * directory. Icon SVG is generated by our own renderer, but it is still escaped
 * wherever it lands inside JS/TS/JSON source rather than being trusted.
 */

import type { Icon, IconFamily } from "./types";
import { pascalCase, slugify } from "./types";

export interface PackageOptions {
  svg: boolean;
  png: boolean;
  react: boolean;
  vue: boolean;
  web: boolean;
  sprite: boolean;
  json: boolean;
  typescript: boolean;
  readme: boolean;
  license: boolean;
  /** PNG sizes to raster. */
  pngSizes: number[];
  licenseType: "MIT" | "Apache-2.0" | "CC0-1.0" | "Proprietary";
}

export const DEFAULT_PACKAGE_OPTIONS: PackageOptions = {
  svg: true,
  png: true,
  react: true,
  vue: true,
  web: true,
  sprite: true,
  json: true,
  typescript: true,
  readme: true,
  license: true,
  pngSizes: [16, 24, 32, 48, 64, 128, 256],
  licenseType: "MIT",
};

export type PackageProgress = (note: string, fraction: number) => void;

/** Strip anything that could escape the archive directory. */
function safeName(name: string): string {
  return slugify(name).replace(/[^a-z0-9-]/g, "") || "icon";
}

/** Escape a string for embedding inside a single-quoted JS/TS literal. */
function jsString(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/'/g, "\\'").replace(/\n/g, "");
}

/** Strip the outer <svg> wrapper, keeping only the drawing. */
function innerSvg(svg: string): string {
  return svg.replace(/^[\s\S]*?<svg[^>]*>/, "").replace(/<\/svg>\s*$/, "");
}

function svgAttrs(svg: string): Record<string, string> {
  const open = /<svg([^>]*)>/.exec(svg)?.[1] ?? "";
  const attrs: Record<string, string> = {};
  for (const m of open.matchAll(/([a-zA-Z-]+)="([^"]*)"/g)) attrs[m[1]!] = m[2]!;
  return attrs;
}

/* ── Raster ───────────────────────────────────────────────────────────────── */

/**
 * Rasterise an SVG string to PNG bytes.
 *
 * Uses an <img> with a data URL rather than `createImageBitmap(blob)`. The
 * bitmap route looks cleaner and silently produced ZERO png files in Chromium,
 * which does not decode SVG blobs that way, the export shipped without its
 * PNG folder and nothing said so. An <img> decodes SVG in every browser.
 *
 * The SVG is inlined as a data URL (not an object URL) because a data URL
 * carries no origin, which keeps the canvas untainted so `toBlob` can read it.
 */
async function rasterise(svg: string, size: number): Promise<Uint8Array | null> {
  // The source may not declare explicit pixel dimensions; an <img> needs them.
  const sized = svg.replace(
    /<svg\b([^>]*)>/,
    (m, attrs: string) =>
      `<svg${attrs.replace(/\s(width|height)="[^"]*"/g, "")} width="${size}" height="${size}">`,
  );
  const url = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(sized)}`;

  const img = await new Promise<HTMLImageElement | null>((resolve) => {
    const el = new Image();
    el.decoding = "sync";
    el.onload = () => resolve(el);
    el.onerror = () => resolve(null);
    el.src = url;
  });
  if (!img) return null;

  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");
  if (!ctx) return null;
  ctx.drawImage(img, 0, 0, size, size);

  const out: Blob | null = await new Promise((r) => canvas.toBlob(r, "image/png"));
  canvas.width = canvas.height = 0;
  return out ? new Uint8Array(await out.arrayBuffer()) : null;
}

/* ── Generators ───────────────────────────────────────────────────────────── */

function reactComponent(icon: Icon): string {
  const name = pascalCase(icon.name);
  const attrs = svgAttrs(icon.svg);
  const body = innerSvg(icon.svg)
    .replace(/stroke-width=/g, "strokeWidth=")
    .replace(/stroke-linecap=/g, "strokeLinecap=")
    .replace(/stroke-linejoin=/g, "strokeLinejoin=")
    .replace(/fill-rule=/g, "fillRule=")
    .replace(/clip-rule=/g, "clipRule=");

  return `import * as React from "react";

export interface ${name}Props extends React.SVGProps<SVGSVGElement> {
  size?: number | string;
}

/** ${icon.description || icon.name} */
export const ${name} = React.forwardRef<SVGSVGElement, ${name}Props>(
  ({ size = ${attrs.width ?? 24}, ...props }, ref) => (
    <svg
      ref={ref}
      xmlns="http://www.w3.org/2000/svg"
      viewBox="${attrs.viewBox ?? "0 0 24 24"}"
      width={size}
      height={size}
      fill="none"
      stroke="currentColor"
      strokeWidth={${attrs["stroke-width"] ?? 1.5}}
      strokeLinecap="${attrs["stroke-linecap"] ?? "round"}"
      strokeLinejoin="${attrs["stroke-linejoin"] ?? "round"}"
      aria-hidden={props["aria-label"] ? undefined : true}
      {...props}
    >
      ${body}
    </svg>
  ),
);

${name}.displayName = "${name}";
export default ${name};
`;
}

function vueComponent(icon: Icon): string {
  const attrs = svgAttrs(icon.svg);
  return `<script setup lang="ts">
defineProps<{ size?: number | string }>();
</script>

<template>
  <svg
    xmlns="http://www.w3.org/2000/svg"
    :viewBox="'${attrs.viewBox ?? "0 0 24 24"}'"
    :width="size ?? ${attrs.width ?? 24}"
    :height="size ?? ${attrs.height ?? 24}"
    fill="none"
    stroke="currentColor"
    stroke-width="${attrs["stroke-width"] ?? 1.5}"
    stroke-linecap="${attrs["stroke-linecap"] ?? "round"}"
    stroke-linejoin="${attrs["stroke-linejoin"] ?? "round"}"
  >
    ${innerSvg(icon.svg)}
  </svg>
</template>
`;
}

function buildSprite(icons: Icon[], family: IconFamily): string {
  const symbols = icons
    .map(
      (i) =>
        `<symbol id="${safeName(i.slug)}" viewBox="0 0 ${family.dna.canvas.width} ${family.dna.canvas.height}">${innerSvg(i.svg)}</symbol>`,
    )
    .join("\n  ");
  return `<svg xmlns="http://www.w3.org/2000/svg" style="display:none">\n  ${symbols}\n</svg>\n`;
}

function buildReadme(family: IconFamily, icons: Icon[], opts: PackageOptions): string {
  const pkg = `@gigai-iconlab/${safeName(family.slug)}`;
  return `# ${family.name}

${family.description || `An icon family of ${icons.length} icons, built with GigAI IconLab.`}

- **Icons:** ${icons.length}
- **Family version:** ${family.version}
- **Grid:** ${family.dna.canvas.width}×${family.dna.canvas.height}
- **Stroke:** ${family.dna.stroke.width} · ${family.dna.stroke.linecap} cap · ${family.dna.stroke.linejoin} join
- **Corner radius:** ${family.dna.geometry.cornerRadius}
- **Style:** ${family.dna.style}
- **Color:** \`currentColor\` - icons inherit the surrounding text color

## What's inside

| Folder | Contents |
|---|---|
${opts.svg ? "| `svg/` | Source SVGs, one per icon |\n" : ""}${opts.png ? `| \`png/\` | Rasters at ${opts.pngSizes.join(", ")}px |\n` : ""}${opts.react ? "| `react/` | React components (forwardRef, typed) |\n" : ""}${opts.vue ? "| `vue/` | Vue 3 SFCs |\n" : ""}${opts.sprite ? "| `sprite/` | Single SVG sprite with `<symbol>` ids |\n" : ""}${opts.json ? "| `metadata/` | `icons.json`, `family.json`, `icon-dna.json` |\n" : ""}
## Usage

### React

\`\`\`tsx
import { ${icons.slice(0, 3).map((i) => pascalCase(i.name)).join(", ") || "Icon"} } from "${pkg}";

<${pascalCase(icons[0]?.name ?? "Icon")} size={24} className="text-slate-700" />
\`\`\`

Icons use \`currentColor\`, so color them with CSS rather than props.

### Sprite

\`\`\`html
<svg><use href="/sprite/${safeName(family.slug)}.svg#${safeName(icons[0]?.slug ?? "icon")}" /></svg>
\`\`\`

## Consistency

Every icon in this family was rendered from one shared Icon DNA, the same grid,
stroke, corner radius and padding, so they align optically without manual
adjustment. Adding icons later reuses that DNA, and new icons will match these.

## Originality

Each icon was screened against the others in this family and against the
references used to build it. That screening is **not** a search of every icon
that exists, and it is **not** legal clearance. Check anything you intend to
ship commercially.

---

Generated by [GigAI IconLab](https://gigai.tools/icon-lab) · family \`${family.familyCode}\` · v${family.version}
`;
}

