/* ── Build ────────────────────────────────────────────────────────────────── */

export async function buildPackage(
  family: IconFamily,
  icons: Icon[],
  opts: PackageOptions = DEFAULT_PACKAGE_OPTIONS,
  onProgress?: PackageProgress,
): Promise<Blob> {
  const progress = onProgress ?? (() => {});
  const files: Record<string, Uint8Array> = {};
  const enc = new TextEncoder();
  const root = safeName(family.slug) || "icons";
  const put = (path: string, text: string) => {
    files[`${root}/${path}`] = enc.encode(text);
  };

  progress("Writing SVG files…", 0.05);
  if (opts.svg) for (const i of icons) put(`svg/${safeName(i.slug)}.svg`, i.svg);

  if (opts.png) {
    let done = 0;
    let written = 0;
    const total = icons.length * opts.pngSizes.length;
    for (const icon of icons) {
      for (const size of opts.pngSizes) {
        const bytes = await rasterise(icon.svg, size);
        if (bytes) {
          files[`${root}/png/${size}/${safeName(icon.slug)}.png`] = bytes;
          written++;
        }
        done++;
        if (done % 10 === 0) progress(`Rendering PNGs: ${done} of ${total}`, 0.05 + (done / total) * 0.5);
      }
    }
    // A requested format producing nothing must be visible in the package, not
    // discovered by the user when they open the ZIP and find no png/ folder.
    if (written === 0) {
      put(
        "png/README.txt",
        "PNG rasterisation produced no files in this browser.\n\n" +
          "The SVGs in svg/ are the source and scale to any size. To generate PNGs,\n" +
          "open them in a design tool, or use the SVG to PNG converter at\n" +
          "https://gigai.tools/svg-to-png\n",
      );
    }
  }

  progress("Generating components…", 0.6);
  if (opts.react) {
    for (const i of icons) put(`react/${pascalCase(i.name)}.tsx`, reactComponent(i));
    put(
      "react/index.ts",
      icons.map((i) => `export { ${pascalCase(i.name)} } from "./${pascalCase(i.name)}";`).join("\n") + "\n",
    );
  }
  if (opts.vue) {
    for (const i of icons) put(`vue/${pascalCase(i.name)}.vue`, vueComponent(i));
    put(
      "vue/index.ts",
      icons.map((i) => `export { default as ${pascalCase(i.name)} } from "./${pascalCase(i.name)}.vue";`).join("\n") + "\n",
    );
  }
  if (opts.sprite) put(`sprite/${root}.svg`, buildSprite(icons, family));

  if (opts.web) {
    put(
      "web/icons.css",
      `/* ${family.name}: sprite helpers. Icons inherit color from the element. */\n` +
        `.icon { width: 1em; height: 1em; display: inline-block; vertical-align: -0.125em; fill: none; stroke: currentColor; }\n`,
    );
  }

  progress("Writing metadata…", 0.75);
  if (opts.json) {
    put(
      "metadata/icons.json",
      JSON.stringify(
        icons.map((i) => ({
          name: i.name,
          slug: i.slug,
          description: i.description,
          category: i.category,
          tags: i.tags,
          fingerprint: i.fingerprint,
          originalityScore: i.originalityScore,
          consistencyScore: i.consistencyScore,
        })),
        null,
        2,
      ),
    );
    put(
      "metadata/family.json",
      JSON.stringify(
        {
          name: family.name,
          slug: family.slug,
          familyCode: family.familyCode,
          version: family.version,
          description: family.description,
          iconCount: icons.length,
          categories: family.categories,
          generatedBy: "GigAI IconLab",
        },
        null,
        2,
      ),
    );
    put("metadata/icon-dna.json", JSON.stringify(family.dna, null, 2));
  }

  if (opts.typescript) {
    put(
      "index.ts",
      `${opts.react ? 'export * from "./react";\n' : ""}export type IconName =\n${
        icons.map((i) => `  | '${jsString(i.slug)}'`).join("\n") || "  | never"
      };\n\nexport const ICON_NAMES: IconName[] = [\n${icons
        .map((i) => `  '${jsString(i.slug)}',`)
        .join("\n")}\n];\n`,
    );
    put(
      "package.json",
      JSON.stringify(
        {
          name: `@gigai-iconlab/${root}`,
          version: family.version,
          description: family.description || `${family.name} icon family`,
          license: opts.licenseType,
          sideEffects: false,
          main: "index.ts",
          types: "index.ts",
          keywords: ["icons", "svg", "react", "vue", root],
        },
        null,
        2,
      ),
    );
  }

  if (opts.readme) put("README.md", buildReadme(family, icons, opts));
  if (opts.license) put("LICENSE", LICENSES[opts.licenseType]);

  progress("Compressing…", 0.9);
  const { zip } = await import("fflate");
  const bytes = await new Promise<Uint8Array>((resolve, reject) => {
    zip(files, { level: 6 }, (err, data) => (err ? reject(err) : resolve(data)));
  });

  progress("Ready", 1);
  return new Blob([bytes as BlobPart], { type: "application/zip" });
}
